on conflict (id) do nothing;

on conflict (slug) do nothing;

update public.products
set description = brand || ' ' || name || ' — matériel proposé par Mark Computer. Contactez le magasin pour la disponibilité et les détails exacts.'
where description = '';

update public.products set rating = 4.5 where rating is null;

update public.products
set image_paths = case
  when image_path = 'seed/builder-parts.jpg' then jsonb_build_array(image_path)
  else jsonb_build_array(image_path, 'seed/builder-parts.jpg')
end
where image_paths = '[]'::jsonb and image_path is not null;

update public.products p
set sku = 'MC-' || lpad(s.rn::text, 4, '0')
from (select id, row_number() over (order by slug) as rn from public.products) s
where p.id = s.id and p.sku = '';